use pinning::{Note, pin, unpin, ordered_pinned_first};

#[test]
fn test_pin_sets_pinned_flag() {
    let mut notes = vec![
        Note { id: "a".to_string(), content: "first".to_string(), pinned: false },
        Note { id: "b".to_string(), content: "second".to_string(), pinned: false },
    ];

    pin(&mut notes, "a");

    assert!(notes[0].pinned, "Pinning note 'a' should set its pinned flag to true");
    assert!(!notes[1].pinned, "Pinning note 'a' should not affect note 'b'");
}

#[test]
fn test_unpin_clears_pinned_flag() {
    let mut notes = vec![
        Note { id: "x".to_string(), content: "first".to_string(), pinned: true },
        Note { id: "y".to_string(), content: "second".to_string(), pinned: false },
    ];

    unpin(&mut notes, "x");

    assert!(!notes[0].pinned, "Unpinning note 'x' should clear its pinned flag");
    assert!(!notes[1].pinned, "Unpinning note 'x' should not affect note 'y'");
}

#[test]
fn test_pin_nonexistent_id_is_harmless_noop() {
    let mut notes = vec![
        Note { id: "1".to_string(), content: "a".to_string(), pinned: false },
        Note { id: "2".to_string(), content: "b".to_string(), pinned: true },
    ];

    pin(&mut notes, "nonexistent");

    assert!(!notes[0].pinned, "Pinning non-existent ID should not modify existing notes");
    assert!(notes[1].pinned, "Pinning non-existent ID should not modify existing notes");
}

