    let mut notes = vec![
        Note { id: "1".to_string(), content: "a".to_string(), pinned: true },
        Note { id: "2".to_string(), content: "b".to_string(), pinned: false },
    ];

    unpin(&mut notes, "nonexistent");

    assert!(notes[0].pinned, "Unpinning non-existent ID should not modify existing notes");
    assert!(!notes[1].pinned, "Unpinning non-existent ID should not modify existing notes");
}

#[test]
fn test_ordered_pinned_first_preserves_relative_order() {
    let notes = vec![
        Note { id: "a".to_string(), content: "1".to_string(), pinned: false },
        Note { id: "b".to_string(), content: "2".to_string(), pinned: true },
        Note { id: "c".to_string(), content: "3".to_string(), pinned: false },
        Note { id: "d".to_string(), content: "4".to_string(), pinned: true },
        Note { id: "e".to_string(), content: "5".to_string(), pinned: false },
    ];

    let ordered = ordered_pinned_first(&notes);

    // 1. Verify all pinned notes appear before any unpinned note
