    let unpinned_ids: Vec<&str> = ordered
        .iter()
        .filter(|n| !n.pinned)
        .map(|n| n.id.as_str())
        .collect();
    assert_eq!(unpinned_ids, vec!["a", "c", "e"], "Unpinned notes should maintain original relative order");
}
